using Microsoft.AspNetCore.Identity.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;

namespace ShipmentTracker.Data;

public class ApplicationDbContext(DbContextOptions<ApplicationDbContext> options) : IdentityDbContext<ApplicationUser>(options)
{
    public DbSet<Shipment> Shipments => Set<Shipment>();

    protected override void OnModelCreating(ModelBuilder builder)
    {
        base.OnModelCreating(builder);

        builder.Entity<Shipment>(e =>
        {
            e.HasIndex(s => s.TrackingNumber).IsUnique();
        });
    }
}

﻿@page "/"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@inject IShipmentService ShipmentService
@inject NavigationManager Navigation

<PageTitle>ShipmentTracker — Home</PageTitle>

<h1>Shipment Tracker</h1>
<p class="lead">Track your shipments in real time.</p>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">Track a Shipment</h5>
        <div class="input-group">
            <input type="text" class="form-control" placeholder="Enter tracking number (e.g. TRK-1001)"
                   @bind="trackingInput" @bind:event="oninput"
                   @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="TrackShipment">Track</button>
        </div>
        @if (showNotFound)
        {
            <div class="alert alert-warning mt-2 mb-0">No shipment found for that tracking number.</div>
        }
    </div>
</div>

@if (recentShipment is not null)
{
    <div class="card">
        <div class="card-body">
            <h5 class="card-title">@recentShipment.TrackingNumber</h5>
            <p><strong>Description:</strong> @recentShipment.Description</p>
            <p><strong>Status:</strong> <span class="badge bg-@GetStatusColor(recentShipment.Status)">@recentShipment.Status</span></p>
            <p><strong>Origin:</strong> @recentShipment.Origin &rarr; <strong>Destination:</strong> @recentShipment.Destination</p>
            <p><strong>Estimated Delivery:</strong> @recentShipment.EstimatedDelivery.ToString("MMM dd, yyyy")</p>
        </div>
    </div>
}

@code {
    private string trackingInput = string.Empty;
    private Shipment? recentShipment;
    private bool showNotFound;

    private async Task TrackShipment()
    {
        showNotFound = false;
        if (string.IsNullOrWhiteSpace(trackingInput)) return;

        recentShipment = await ShipmentService.GetShipmentByTrackingNumberAsync(trackingInput.Trim());
        showNotFound = recentShipment is null;
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await TrackShipment();
    }

    private static string GetStatusColor(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "success",
        ShipmentStatus.InTransit => "info",
        ShipmentStatus.OutForDelivery => "primary",
